import React from 'react';
import Leave from './Leave';
import ViewMyLeaves from './ViewMyLeaves';

function LeaveDashboard({ user }) {
  return (
    <div style={{
      display: 'flex',
      gap: '30px',
      padding: '20px',
      alignItems: 'flex-start',
      maxWidth: '1200px',
      margin: '0 auto',
    }}>
      <div style={{
        flex: 1,
        minWidth: '320px',
        background: 'white',
        padding: '20px',
        borderRadius: '8px',
        boxShadow: '0 0 10px rgba(0,0,0,0.1)',
      }}>
        <Leave />
      </div>

      <div style={{
        flex: 1,
        minWidth: '320px',
        background: 'white',
        padding: '20px',
        borderRadius: '8px',
        boxShadow: '0 0 10px rgba(0,0,0,0.1)',
      }}>
        <ViewMyLeaves user={user} />
      </div>
    </div>
  );
}

export default LeaveDashboard;
